.cu-toast {
  display: grid;
  gap: var(--cu-space-1);
  min-inline-size: 16rem;
  max-inline-size: min(100%, 24rem);
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
  border-radius: var(--cu-radius-md);
  border-inline-start: 4px solid var(--cu-color-palette-brand);
  color: var(--cu-color-fg-default);
  background: var(--cu-color-background-default);
  box-shadow: var(--cu-shadow-md);
}

.cu-toast--success {
  border-inline-start-color: color-mix(in srgb, var(--cu-color-palette-brand) 80%, green);
}

.cu-toast--warning {
  border-inline-start-color: color-mix(in srgb, var(--cu-color-palette-brand) 80%, orange);
}

.cu-toast--error {
  border-inline-start-color: color-mix(in srgb, var(--cu-color-palette-brand) 80%, red);
}

.cu-toast__title {
  font-weight: 700;
}

.cu-toast__description {
  font-size: 0.9375rem;
  line-height: 1.5;
}

.cu-toast__close {
  justify-self: start;
  margin-block-start: var(--cu-space-1);
}

import type { ReactNode } from 'react'
import './styles.css'

export type ToastStatus = 'info' | 'success' | 'warning' | 'error'

export interface ToastProps {
  open: boolean
  title: string
  description: ReactNode
  status?: ToastStatus
  closeLabel: string
  onOpenChange?: (open: boolean) => void
  className?: string
}

export function Toast({
  open,
  title,
  description,
  status = 'info',
  closeLabel,
  onOpenChange,
  className,
}: ToastProps) {
  if (!open) return null

  const classes = ['cu-toast', `cu-toast--${status}`, className].filter(Boolean).join(' ')

  return (
    <div
      aria-label={title}
      className={classes}
      data-ai-role="toast" data-ai-intent="notify-transient"
      data-ai-state={status}
      role="status"
      aria-live={status === 'error' ? 'assertive' : 'polite'}
    >
      <div className="cu-toast__title">{title}</div>
      <div className="cu-toast__description">{description}</div>
      <button
        className="cu-toast__close"
        onClick={() => onOpenChange?.(false)}
        type="button"
      >
        {closeLabel}
      </button>
    </div>
  )
}
